#!/usr/bin/env python3
"""seqlite.py - a minimal reimplementation of GNU seq.

Supports:
    seq LAST
    seq FIRST LAST
    seq FIRST INCREMENT LAST
Options:
    -s SEP   use SEP to separate numbers (default: newline)
    -w       equalize width by padding with leading zeros
"""
import sys


def parse_number(text):
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        sys.stderr.write("seq: invalid floating point argument: '%s'\n" % text)
        sys.exit(1)


def count_decimals(text):
    return len(text.partition(".")[2]) if "." in text else 0


def main(argv):
    sep = "\n"
    pad_width = False
    numbers = []

    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "-s":
            i += 1
            if i >= len(argv):
                sys.stderr.write("seq: option requires an argument -- 's'\n")
                sys.exit(1)
            sep = argv[i]
        elif arg.startswith("-s") and len(arg) > 2:
            sep = arg[2:]
        elif arg == "-w":
            pad_width = True
        elif arg.startswith("-") and len(arg) > 1 and arg != "-w" and not _is_number(arg):
            # unknown option
            sys.stderr.write("seq: invalid option -- '%s'\n" % arg.lstrip("-")[:1])
            sys.exit(1)
        else:
            numbers.append(arg)
        i += 1

    if not numbers or len(numbers) > 3:
        sys.stderr.write(
            "Usage: seqlite.py [-s SEP] [-w] [FIRST [INCREMENT]] LAST\n"
        )
        sys.exit(1)

    first, step, last = (
        parse_number(numbers[0]),
        1,
        None,
    )
    if len(numbers) == 1:
        last = first
        first, step = 1, 1
    elif len(numbers) == 2:
        first, last = parse_number(numbers[0]), parse_number(numbers[1])
    else:
        first, step, last = (parse_number(n) for n in numbers)

    if step == 0:
        sys.stderr.write("seq: invalid Zero increment value: '%s'\n" % numbers[-2])
        sys.exit(1)

    prec = max(count_decimals(n) for n in numbers)

    values = []
    eps = 1e-9 * max(1.0, abs(first), abs(step), abs(last))
    idx = 0
    while True:
        raw = first + idx * step
        val = round(raw, prec)
        if step > 0 and val > last + eps:
            break
        if step < 0 and val < last - eps:
            break
        values.append(val)
        idx += 1

    rendered = [("%.*f" % (prec, v)) for v in values]
    if pad_width and rendered:
        width = max(len(s) for s in rendered)
        rendered = [s.rjust(width, "0") for s in rendered]

    out = ""
    if rendered:
        out = sep.join(rendered) + "\n"
    sys.stdout.write(out)


def _is_number(text):
    try:
        float(text)
        return True
    except ValueError:
        return False


if __name__ == "__main__":
    main(sys.argv[1:])

